import{_ as d,a as t,o,a4 as r}from"./chunks/framework.-FZumj2l.js";const p=JSON.parse('{"title":"Booking Detail","description":"","frontmatter":{"outline":false,"examples":[{"id":"admin-booking-detail-gql","title":"Booking Detail","description":"Fetch a single booking with its sub-type, full booking window, and embedded order / order-item summaries.","query":"query AdminBooking($id: ID!) {\\n  adminBooking(id: $id) {\\n    id\\n    _id\\n    orderId\\n    orderIncrementId\\n    orderItemId\\n    productId\\n    productSku\\n    productName\\n    bookingType\\n    qty\\n    from\\n    to\\n    fromFormatted\\n    toFormatted\\n    bookingProductEventTicketId\\n    createdAt\\n    order\\n    orderItem\\n    paymentMethod\\n    paymentTitle\\n    shippingMethod\\n    shippingTitle\\n    billingAddress\\n    shippingAddress\\n    invoices\\n    shipments\\n    refunds\\n  }\\n}\\n","variables":"{\\n  \\"id\\": \\"/api/admin/bookings/1\\"\\n}\\n","response":"{\\n  \\"data\\": {\\n    \\"adminBooking\\": {\\n      \\"id\\": \\"/api/admin/bookings/1\\",\\n      \\"_id\\": 1,\\n      \\"orderId\\": 8,\\n      \\"orderIncrementId\\": \\"2000000008\\",\\n      \\"orderItemId\\": 42,\\n      \\"productId\\": 99,\\n      \\"productSku\\": \\"BK-EVENT-01\\",\\n      \\"productName\\": \\"Concert Ticket\\",\\n      \\"bookingType\\": \\"event\\",\\n      \\"qty\\": 2,\\n      \\"from\\": 1716220800,\\n      \\"to\\": 1716224400,\\n      \\"fromFormatted\\": \\"20 May, 2026 12:00PM\\",\\n      \\"toFormatted\\": \\"20 May, 2026 13:00PM\\",\\n      \\"bookingProductEventTicketId\\": 5,\\n      \\"createdAt\\": \\"2026-05-20 10:00:00\\",\\n      \\"order\\": {\\n        \\"id\\": 8,\\n        \\"incrementId\\": \\"00000000008\\",\\n        \\"status\\": \\"processing\\",\\n        \\"customerName\\": \\"John Doe\\",\\n        \\"customerEmail\\": \\"john.doe@example.com\\",\\n        \\"grandTotal\\": 240,\\n        \\"orderCurrencyCode\\": \\"USD\\"\\n      },\\n      \\"orderItem\\": {\\n        \\"id\\": 42,\\n        \\"sku\\": \\"BK-EVENT-01\\",\\n        \\"name\\": \\"Concert Ticket\\",\\n        \\"qtyOrdered\\": 2\\n      },\\n      \\"paymentMethod\\": \\"moneytransfer\\",\\n      \\"paymentTitle\\": \\"Money Transfer\\",\\n      \\"shippingMethod\\": null,\\n      \\"shippingTitle\\": null,\\n      \\"billingAddress\\": {\\n        \\"id\\": 4939,\\n        \\"addressType\\": \\"order_billing\\",\\n        \\"firstName\\": \\"John\\",\\n        \\"lastName\\": \\"Doe\\",\\n        \\"companyName\\": \\"Acme Inc.\\",\\n        \\"address\\": \\"123 Main St\\\\nApt 4B\\",\\n        \\"city\\": \\"New York\\",\\n        \\"state\\": \\"NY\\",\\n        \\"country\\": \\"US\\",\\n        \\"postcode\\": \\"10001\\",\\n        \\"email\\": \\"john@example.com\\",\\n        \\"phone\\": \\"1234567890\\"\\n      },\\n      \\"shippingAddress\\": null,\\n      \\"invoices\\": [\\n        {\\n          \\"id\\": 559,\\n          \\"incrementId\\": \\"559\\",\\n          \\"state\\": \\"paid\\",\\n          \\"baseGrandTotal\\": 204,\\n          \\"formattedBaseGrandTotal\\": \\"$204.00\\",\\n          \\"createdAt\\": \\"2026-05-19 13:11:39\\"\\n        }\\n      ],\\n      \\"shipments\\": [],\\n      \\"refunds\\": []\\n    }\\n  }\\n}\\n"}]},"headers":[],"relativePath":"api/graphql-api/admin/sales/bookings/detail.md","filePath":"api/graphql-api/admin/sales/bookings/detail.md","lastUpdated":1783327468000}'),n={name:"api/graphql-api/admin/sales/bookings/detail.md"};function c(i,e,a,s,h,l){return o(),t("div",null,e[0]||(e[0]=[r('<h1 id="booking-detail" tabindex="-1">Booking Detail <a class="header-anchor" href="#booking-detail" aria-label="Permalink to &quot;Booking Detail&quot;">​</a></h1><p>GraphQL counterpart of <code>GET /api/admin/bookings/{id}</code>. Returns a single booking with everything the listing leaves out — the booking sub-type, the linked event-ticket id, embedded summaries of the parent order and order line item, and the underlying order&#39;s billing/shipping address, payment &amp; shipping info, and its invoices / shipments / refunds — so you can render the booking view (and the order it opens) without any follow-up fetch.</p><h2 id="operation" tabindex="-1">Operation <a class="header-anchor" href="#operation" aria-label="Permalink to &quot;Operation&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Operation</th><th>Type</th></tr></thead><tbody><tr><td><code>adminBooking(id: ID!)</code></td><td>Query</td></tr></tbody></table><p>Pass the booking IRI (<code>/api/admin/bookings/{id}</code>) as <code>id</code>. Permission: <code>sales.bookings.view</code>.</p><div class="warning custom-block"><p class="custom-block-title">order, orderItem, billingAddress, shippingAddress, invoices, shipments and refunds are returned whole</p><p><code>order</code>, <code>orderItem</code>, <code>billingAddress</code>, <code>shippingAddress</code>, <code>invoices</code>, <code>shipments</code> and <code>refunds</code> are returned as whole JSON objects/arrays — <strong>query them bare, without a sub-selection</strong> (<code>billingAddress</code>, not <code>billingAddress { … }</code>; <code>invoices</code>, not <code>invoices { edges { node { … } } }</code>). The complete object/array comes back. The keys inside each are listed below for reference.</p></div><h2 id="fields" tabindex="-1">Fields <a class="header-anchor" href="#fields" aria-label="Permalink to &quot;Fields&quot;">​</a></h2><p>The booking window is exposed two ways: <code>from</code> / <code>to</code> are raw <strong>unix timestamps</strong> (integers), and <code>fromFormatted</code> / <code>toFormatted</code> are the same instants pre-rendered as human-readable <code>d M, Y H:iA</code> strings (e.g. <code>&quot;20 May, 2026 12:00PM&quot;</code>). For booking sub-types with no time window all four can be <code>null</code>.</p><table tabindex="0"><thead><tr><th>Field</th><th>Type</th><th>Description</th></tr></thead><tbody><tr><td><code>id</code></td><td><code>ID</code></td><td>Resource identifier (IRI form).</td></tr><tr><td><code>_id</code></td><td><code>Int</code></td><td>Numeric booking id.</td></tr><tr><td><code>orderId</code></td><td><code>Int</code></td><td>Id of the parent order.</td></tr><tr><td><code>orderIncrementId</code></td><td><code>String</code></td><td>Human-facing number of the parent order.</td></tr><tr><td><code>orderItemId</code></td><td><code>Int</code></td><td>Id of the order line item this booking was created from.</td></tr><tr><td><code>productId</code></td><td><code>Int</code></td><td>Id of the booked product.</td></tr><tr><td><code>productSku</code></td><td><code>String</code></td><td>SKU of the booked product.</td></tr><tr><td><code>productName</code></td><td><code>String</code></td><td>Product name as ordered.</td></tr><tr><td><code>bookingType</code></td><td><code>String</code></td><td>Booking sub-type — one of <code>default</code>, <code>appointment</code>, <code>event</code>, <code>rental</code>, <code>table</code>.</td></tr><tr><td><code>qty</code></td><td><code>Int</code></td><td>Quantity booked on this line.</td></tr><tr><td><code>from</code></td><td><code>Int</code></td><td>Start of the booking window as a <strong>unix timestamp</strong> (null for non-time-based bookings).</td></tr><tr><td><code>to</code></td><td><code>Int</code></td><td>End of the booking window as a <strong>unix timestamp</strong> (null for non-time-based bookings).</td></tr><tr><td><code>fromFormatted</code></td><td><code>String</code></td><td><code>from</code> pre-rendered as a <code>d M, Y H:iA</code> string.</td></tr><tr><td><code>toFormatted</code></td><td><code>String</code></td><td><code>to</code> pre-rendered as a <code>d M, Y H:iA</code> string.</td></tr><tr><td><code>bookingProductEventTicketId</code></td><td><code>Int</code></td><td>Linked event-ticket id (set only when <code>bookingType</code> is <code>event</code>).</td></tr><tr><td><code>createdAt</code></td><td><code>String</code></td><td>When the parent order was created.</td></tr><tr><td><code>order</code></td><td><code>Object</code></td><td>Summary of the parent order — see the table below.</td></tr><tr><td><code>orderItem</code></td><td><code>Object</code></td><td>Summary of the parent order line item — see the table below.</td></tr><tr><td><code>paymentMethod</code></td><td><code>String</code></td><td>The order&#39;s payment method code (e.g. <code>moneytransfer</code>).</td></tr><tr><td><code>paymentTitle</code></td><td><code>String</code></td><td>The payment method&#39;s display title.</td></tr><tr><td><code>shippingMethod</code></td><td><code>String</code></td><td>The order&#39;s shipping method code — <code>null</code> when the order had no shipping method.</td></tr><tr><td><code>shippingTitle</code></td><td><code>String</code></td><td>The shipping method&#39;s display title — <code>null</code> when there was no shipping method.</td></tr><tr><td><code>billingAddress</code></td><td><code>JSON</code></td><td>The order&#39;s billing address object, or <code>null</code> — see below.</td></tr><tr><td><code>shippingAddress</code></td><td><code>JSON</code></td><td>The order&#39;s shipping address object, or <code>null</code> — see below.</td></tr><tr><td><code>invoices</code></td><td><code>JSON</code></td><td>Array of the order&#39;s invoice summaries — empty when none. See below.</td></tr><tr><td><code>shipments</code></td><td><code>JSON</code></td><td>Array of the order&#39;s shipment summaries — empty when none. See below.</td></tr><tr><td><code>refunds</code></td><td><code>JSON</code></td><td>Array of the order&#39;s refund summaries — empty when none. See below.</td></tr></tbody></table><h3 id="order-fields-order" tabindex="-1">Order fields (<code>order</code>) <a class="header-anchor" href="#order-fields-order" aria-label="Permalink to &quot;Order fields (`order`)&quot;">​</a></h3><p>A slim summary of the order this booking belongs to, so you can render the booking view without a separate order fetch. <code>order</code> is returned as a whole JSON object — query it as a bare field (<code>order</code>), you cannot sub-select its keys in the query. The keys below are returned inside that object for reference.</p><table tabindex="0"><thead><tr><th>Field</th><th>Type</th><th>Description</th></tr></thead><tbody><tr><td><code>id</code></td><td><code>Int</code></td><td>Order id.</td></tr><tr><td><code>incrementId</code></td><td><code>String</code></td><td>Human-facing order number.</td></tr><tr><td><code>status</code></td><td><code>String</code></td><td>Order status — e.g. <code>complete</code>, <code>processing</code>, <code>pending</code>.</td></tr><tr><td><code>customerName</code></td><td><code>String</code></td><td>Name of the customer who placed the order.</td></tr><tr><td><code>customerEmail</code></td><td><code>String</code></td><td>Email of the customer who placed the order.</td></tr><tr><td><code>grandTotal</code></td><td><code>Float</code></td><td>Order grand total (order currency).</td></tr><tr><td><code>orderCurrencyCode</code></td><td><code>String</code></td><td>Currency the order was placed in (e.g. <code>USD</code>).</td></tr></tbody></table><h3 id="order-item-fields-orderitem" tabindex="-1">Order item fields (<code>orderItem</code>) <a class="header-anchor" href="#order-item-fields-orderitem" aria-label="Permalink to &quot;Order item fields (`orderItem`)&quot;">​</a></h3><p>A slim summary of the order line item this booking was created from. <code>orderItem</code> is returned as a whole JSON object — query it as a bare field (<code>orderItem</code>), you cannot sub-select its keys in the query. The keys below are returned inside that object for reference.</p><table tabindex="0"><thead><tr><th>Field</th><th>Type</th><th>Description</th></tr></thead><tbody><tr><td><code>id</code></td><td><code>Int</code></td><td>Order-item id.</td></tr><tr><td><code>sku</code></td><td><code>String</code></td><td>SKU of the ordered item.</td></tr><tr><td><code>name</code></td><td><code>String</code></td><td>Product name as ordered.</td></tr><tr><td><code>qtyOrdered</code></td><td><code>Float</code></td><td>Quantity ordered for this line item.</td></tr></tbody></table><h3 id="address-objects-billingaddress-shippingaddress" tabindex="-1">Address objects (<code>billingAddress</code>, <code>shippingAddress</code>) <a class="header-anchor" href="#address-objects-billingaddress-shippingaddress" aria-label="Permalink to &quot;Address objects (`billingAddress`, `shippingAddress`)&quot;">​</a></h3><p>The order&#39;s billing and shipping addresses, mirroring the admin order view&#39;s address panel. Each is returned as a whole JSON object (or <code>null</code> when the order has none) — query it as a bare field (<code>billingAddress</code>), you cannot sub-select its keys in the query. The keys below are returned inside each object.</p><table tabindex="0"><thead><tr><th>Field</th><th>Type</th><th>Description</th></tr></thead><tbody><tr><td><code>id</code></td><td><code>Int</code></td><td>Address row id.</td></tr><tr><td><code>addressType</code></td><td><code>String</code></td><td><code>order_billing</code> or <code>order_shipping</code>.</td></tr><tr><td><code>firstName</code> / <code>lastName</code></td><td><code>String</code></td><td>Recipient name.</td></tr><tr><td><code>companyName</code></td><td><code>String</code></td><td>Company name — may be <code>null</code>.</td></tr><tr><td><code>address</code></td><td><code>String</code></td><td>Street address (may span multiple lines).</td></tr><tr><td><code>city</code></td><td><code>String</code></td><td>City.</td></tr><tr><td><code>state</code></td><td><code>String</code></td><td>State / province.</td></tr><tr><td><code>country</code></td><td><code>String</code></td><td>Country code (e.g. <code>US</code>).</td></tr><tr><td><code>postcode</code></td><td><code>String</code></td><td>Postal code.</td></tr><tr><td><code>email</code></td><td><code>String</code></td><td>Contact email.</td></tr><tr><td><code>phone</code></td><td><code>String</code></td><td>Contact phone.</td></tr></tbody></table><h3 id="invoices-invoices" tabindex="-1">Invoices (<code>invoices</code>) <a class="header-anchor" href="#invoices-invoices" aria-label="Permalink to &quot;Invoices (`invoices`)&quot;">​</a></h3><p>Slim summaries of the order&#39;s invoices, returned as a whole JSON array (empty when none) — query it as a bare field (<code>invoices</code>), you cannot sub-select its keys in the query. Each entry has the keys below.</p><table tabindex="0"><thead><tr><th>Field</th><th>Type</th><th>Description</th></tr></thead><tbody><tr><td><code>id</code></td><td><code>Int</code></td><td>Invoice id.</td></tr><tr><td><code>incrementId</code></td><td><code>String</code></td><td>Human-facing invoice number.</td></tr><tr><td><code>state</code></td><td><code>String</code></td><td>Invoice state — e.g. <code>paid</code>, <code>pending</code>.</td></tr><tr><td><code>baseGrandTotal</code></td><td><code>Float</code></td><td>Invoice grand total in the store&#39;s base currency.</td></tr><tr><td><code>formattedBaseGrandTotal</code></td><td><code>String</code></td><td>The same total pre-formatted for display.</td></tr><tr><td><code>createdAt</code></td><td><code>String</code></td><td>When the invoice was created.</td></tr></tbody></table><h3 id="shipments-shipments" tabindex="-1">Shipments (<code>shipments</code>) <a class="header-anchor" href="#shipments-shipments" aria-label="Permalink to &quot;Shipments (`shipments`)&quot;">​</a></h3><p>Slim summaries of the order&#39;s shipments, returned as a whole JSON array (empty when none) — query it as a bare field (<code>shipments</code>), you cannot sub-select its keys in the query. Each entry has the keys below.</p><table tabindex="0"><thead><tr><th>Field</th><th>Type</th><th>Description</th></tr></thead><tbody><tr><td><code>id</code></td><td><code>Int</code></td><td>Shipment id.</td></tr><tr><td><code>totalQty</code></td><td><code>Float</code></td><td>Total quantity shipped.</td></tr><tr><td><code>carrierTitle</code></td><td><code>String</code></td><td>Shipping carrier title — may be <code>null</code>.</td></tr><tr><td><code>trackNumber</code></td><td><code>String</code></td><td>Carrier tracking number — may be <code>null</code>.</td></tr><tr><td><code>createdAt</code></td><td><code>String</code></td><td>When the shipment was created.</td></tr></tbody></table><h3 id="refunds-refunds" tabindex="-1">Refunds (<code>refunds</code>) <a class="header-anchor" href="#refunds-refunds" aria-label="Permalink to &quot;Refunds (`refunds`)&quot;">​</a></h3><p>Slim summaries of the order&#39;s refunds, returned as a whole JSON array (empty when none) — query it as a bare field (<code>refunds</code>), you cannot sub-select its keys in the query. Each entry has the keys below.</p><table tabindex="0"><thead><tr><th>Field</th><th>Type</th><th>Description</th></tr></thead><tbody><tr><td><code>id</code></td><td><code>Int</code></td><td>Refund id.</td></tr><tr><td><code>state</code></td><td><code>String</code></td><td>Refund state.</td></tr><tr><td><code>baseGrandTotal</code></td><td><code>Float</code></td><td>Refund grand total in the store&#39;s base currency.</td></tr><tr><td><code>formattedBaseGrandTotal</code></td><td><code>String</code></td><td>The same total pre-formatted for display.</td></tr><tr><td><code>createdAt</code></td><td><code>String</code></td><td>When the refund was created.</td></tr></tbody></table>',27)]))}const u=d(n,[["render",c]]);export{p as __pageData,u as default};
